21	/// Number of bits needed to store height.
22	const HEIGHT_BITS: usize = 5;
23	
24	/// Maximum height of a skip list tower.
25	const MAX_HEIGHT: usize = 1 << HEIGHT_BITS;
26	
27	/// The bits of `refs_and_height` that keep the height.
28	const HEIGHT_MASK: usize = (1 << HEIGHT_BITS) - 1;
29	
30	/// The tower of atomic pointers.
31	///
32	/// The actual size of the tower will vary depending on the height that a node
33	/// was allocated with.
34	#[repr(C)]
35	struct Tower<K, V> {
36	    pointers: [Atomic<Node<K, V>>; 0],
37	}
38	
39	/// A "reference" to a Tower that preserves provenance for accessing the dynamically sized tower.
40	///
41	/// A regular `&'a Tower<K, V>` would not have permission to access any bytes under stacked borrows
42	/// since Tower is a placeholder ZST.
43	///
44	/// Note, under tree borrows this isn't necessary.
45	struct TowerRef<'a, K, V> {
46	    ptr: NonNull<Tower<K, V>>,
47	    _marker: PhantomData<&'a Tower<K, V>>,
48	}
49	
50	impl<K, V> Clone for TowerRef<'_, K, V> {
51	    fn clone(&self) -> Self {
52	        *self
53	    }
54	}
55	impl<K, V> Copy for TowerRef<'_, K, V> {}
