57	impl<'a, K, V> TowerRef<'a, K, V> {
58	    /// Creates a TowerRef.
59	    ///
60	    /// # Safety
61	    ///
62	    /// Same as NonNull::as_ref, except the pointer must be valid for accessing the actual
63	    /// size of the tower.
64	    #[inline]
65	    unsafe fn new(ptr: NonNull<Tower<K, V>>) -> Self {
66	        Self {
67	            ptr,
68	            _marker: PhantomData,
69	        }
70	    }
