121	/// A skip list node.
122	///
123	/// This struct is marked with `repr(C)` so that the specific order of fields is enforced.
124	/// It is important that the tower is the last field since it is dynamically sized. The key,
125	/// reference count, and height are kept close to the tower to improve cache locality during
126	/// skip list traversal.
127	#[repr(C)]
128	struct Node<K, V> {
129	    /// The value.
130	    value: V,
131	
132	    /// The key.
133	    key: K,
134	
135	    /// Keeps the reference count and the height of its tower.
136	    ///
137	    /// The reference count is equal to the number of `Entry`s pointing to this node, plus the
138	    /// number of levels in which this node is installed.
139	    refs_and_height: AtomicUsize,
140	
141	    /// The tower of atomic pointers.
142	    tower: Tower<K, V>,
143	}
