145	/// A "reference" to a Node that preserves provenance for accessing the dynamically sized tower at
146	/// the end of the node allocation.
147	///
148	/// Note, in a few situations below, we also rely on this for preserving write permissions.
149	struct NodeRef<'a, K, V> {
150	    ptr: NonNull<Node<K, V>>,
151	    _marker: PhantomData<&'a Node<K, V>>,
152	}
