161	impl<K, V> Node<K, V> {
162	    /// Allocates a node.
163	    ///
164	    /// The returned node will start with reference count of `ref_count` and the tower will be initialized
165	    /// with null pointers. However, the key and the value will be left uninitialized, and that is
166	    /// why this function is unsafe.
167	    unsafe fn alloc(height: usize, ref_count: usize) -> *mut Self {
168	        let layout = Self::get_layout(height);
169	        unsafe {
170	            let ptr = match Global.allocate(layout) {
171	                Some(ptr) => ptr.as_ptr().cast::<Self>(),
172	                None => handle_alloc_error(layout),
173	            };
174	
175	            ptr::addr_of_mut!((*ptr).refs_and_height)
176	                .write(AtomicUsize::new((height - 1) | (ref_count << HEIGHT_BITS)));
177	            ptr::addr_of_mut!((*ptr).tower.pointers)
178	                .cast::<Atomic<Self>>()
179	                .write_bytes(0, height);
180	            ptr
181	        }
182	    }
183	
184	    /// Deallocates a node.
185	    ///
186	    /// This function will not run any destructors.
187	    unsafe fn dealloc(ptr: *mut Self) {
188	        unsafe {
189	            let height = (*ptr).height();
190	            let layout = Self::get_layout(height);
191	            Global.deallocate(NonNull::new_unchecked(ptr.cast::<u8>()), layout);
192	        }
193	    }
194	
195	    /// Returns the layout of a node with the given `height`.
196	    fn get_layout(height: usize) -> Layout {
197	        assert!((1..=MAX_HEIGHT).contains(&height));
198	
199	        Layout::new::<Self>()
200	            .extend(Layout::array::<Atomic<Self>>(height).unwrap())
201	            .unwrap()
202	            .0
203	            .pad_to_align()
204	    }
205	
206	    /// Returns the height of this node's tower.
207	    #[inline]
208	    fn height(&self) -> usize {
209	        (self.refs_and_height.load(Ordering::Relaxed) & HEIGHT_MASK) + 1
210	    }
211	
212	    /// Attempts to increment the reference count of a node and returns `true` on success.
213	    ///
214	    /// The reference count can be incremented only if it is non-zero.
215	    ///
216	    /// # Panics
217	    ///
218	    /// Panics if the reference count overflows.
219	    #[inline]
220	    unsafe fn try_increment(&self) -> bool {
221	        let mut refs_and_height = self.refs_and_height.load(Ordering::Relaxed);
222	
223	        loop {
224	            // If the reference count is zero, then the node has already been
225	            // queued for deletion. Incrementing it again could lead to a
226	            // double-free.
227	            if refs_and_height & !HEIGHT_MASK == 0 {
228	                return false;
229	            }
230	
231	            // If all bits in the reference count are ones, we're about to overflow it.
232	            let new_refs_and_height = refs_and_height
233	                .checked_add(1 << HEIGHT_BITS)
234	                .expect("SkipList reference count overflow");
235	
236	            // Try incrementing the count.
237	            match self.refs_and_height.compare_exchange_weak(
238	                refs_and_height,
239	                new_refs_and_height,
240	                Ordering::Relaxed,
241	                Ordering::Relaxed,
242	            ) {
243	                Ok(_) => return true,
244	                Err(current) => refs_and_height = current,
245	            }
246	        }
247	    }
248	
249	    /// Drops the key and value of a node, then deallocates it.
250	    #[cold]
251	    unsafe fn finalize(ptr: *mut Self) {
252	        unsafe {
253	            // Call destructors: drop the key and the value.
254	            ptr::drop_in_place(&mut (*ptr).key);
255	            ptr::drop_in_place(&mut (*ptr).value);
256	
257	            // Finally, deallocate the memory occupied by the node.
258	            Self::dealloc(ptr);
259	        }
260	    }
261	}
