264	    /// Creates a NodeRef.
265	    ///
266	    /// # Safety
267	    ///
268	    /// Same as NonNull::as_ref, except the pointer must also be valid for accessing the actual
269	    /// size of the tower at the end of the node.
270	    #[inline]
271	    unsafe fn new(ptr: NonNull<Node<K, V>>) -> Self {
272	        Self {
273	            ptr,
274	            _marker: PhantomData,
275	        }
276	    }
