278	    /// # Safety
279	    ///
280	    /// See [`Shared::as_ref`].
281	    #[inline]
282	    unsafe fn from_shared(shared: Shared<'a, Node<K, V>>) -> Option<Self> {
283	        if let Some(ptr) = NonNull::new(shared.as_raw() as *mut Node<K, V>) {
284	            Some(unsafe { Self::new(ptr) })
285	        } else {
286	            None
287	        }
288	    }
