290	    /// Decrements the reference count of a node, destroying it if the count becomes zero.
291	    #[inline]
292	    unsafe fn decrement(self, guard: &Guard) {
293	        if self
294	            .refs_and_height
295	            .fetch_sub(1 << HEIGHT_BITS, Ordering::Release)
296	            >> HEIGHT_BITS
297	            == 1
298	        {
299	            fence(Ordering::Acquire);
300	            unsafe { guard.defer_unchecked(move || Node::finalize(self.ptr.as_ptr())) }
301	        }
302	    }
303	
304	    /// Decrements the reference count of a node, pinning the thread and destroying the node
305	    /// if the count become zero.
306	    #[inline]
307	    unsafe fn decrement_with_pin<F>(self, parent: &SkipList<K, V>, pin: F)
308	    where
309	        F: FnOnce() -> Guard,
310	    {
311	        if self
312	            .refs_and_height
313	            .fetch_sub(1 << HEIGHT_BITS, Ordering::Release)
314	            >> HEIGHT_BITS
315	            == 1
316	        {
317	            fence(Ordering::Acquire);
318	            let guard = &pin();
319	            parent.check_guard(guard);
320	            unsafe { guard.defer_unchecked(move || Node::finalize(self.ptr.as_ptr())) }
321	        }
322	    }
