324	    /// Marks all pointers in the tower and returns `true` if the level 0 was not marked.
325	    fn mark_tower(self) -> bool {
326	        let height = self.height();
327	
328	        for level in (0..height).rev() {
329	            let tag = unsafe {
330	                // We're loading the pointer only for the tag, so it's okay to use
331	                // `epoch::unprotected()` in this situation.
332	                // TODO(Amanieu): can we use release ordering here?
333	                self.get_level(level)
334	                    .fetch_or(1, Ordering::SeqCst, epoch::unprotected())
335	                    .tag()
336	            };
337	
338	            // If the level 0 pointer was already marked, somebody else removed the node.
339	            if level == 0 && tag == 1 {
340	                return false;
341	            }
342	        }
343	
344	        // We marked the level 0 pointer, therefore we removed the node.
345	        true
346	    }
