348	    /// Returns `true` if the node is removed.
349	    #[inline]
350	    fn is_removed(self) -> bool {
351	        let tag = unsafe {
352	            // We're loading the pointer only for the tag, so it's okay to use
353	            // `epoch::unprotected()` in this situation.
354	            self.get_level(0)
355	                .load(Ordering::Relaxed, epoch::unprotected())
356	                .tag()
357	        };
358	        tag == 1
359	    }
