440	/// Frequently modified data associated with a skip list.
441	struct HotData {
442	    /// The seed for random height generation.
443	    seed: AtomicUsize,
444	
445	    /// The number of entries in the skip list.
446	    len: AtomicUsize,
447	
448	    /// Highest tower currently in use. This value is used as a hint for where
449	    /// to start lookups and never decreases.
450	    max_height: AtomicUsize,
