453	/// A lock-free skip list.
454	// TODO(stjepang): Embed a custom `epoch::Collector` inside `SkipList<K, V>`. Instead of adding
455	// garbage to the default global collector, we should add it to a local collector tied to the
456	// particular skip list instance.
457	//
458	// Since global collector might destroy garbage arbitrarily late in the future, some skip list
459	// methods have `K: 'static` and `V: 'static` bounds. But a local collector embedded in the skip
460	// list would destroy all remaining garbage when the skip list is dropped, so in that case we'd be
461	// able to remove those bounds on types `K` and `V`.
462	//
463	// As a further future optimization, if `!mem::needs_drop::<K>() && !mem::needs_drop::<V>()`
464	// (neither key nor the value have destructors), there's no point in creating a new local
465	// collector, so we should simply use the global one.
466	pub struct SkipList<K, V> {
467	    /// The head of the skip list (just a dummy node, not a real entry).
468	    head: Head<K, V>,
469	
470	    /// The `Collector` associated with this skip list.
471	    collector: Collector,
472	
473	    /// Hot data associated with the skip list, stored in a dedicated cache line.
474	    hot_data: CachePadded<HotData>,
475	}
476	
477	unsafe impl<K: Send + Sync, V: Send + Sync> Send for SkipList<K, V> {}
478	unsafe impl<K: Send + Sync, V: Send + Sync> Sync for SkipList<K, V> {}
479	
480	impl<K, V> SkipList<K, V> {
481	    /// Returns a new, empty skip list.
482	    pub fn new(collector: Collector) -> Self {
483	        Self {
484	            head: Head::new(),
485	            collector,
486	            hot_data: CachePadded::new(HotData {
487	                seed: AtomicUsize::new(1),
488	                len: AtomicUsize::new(0),
489	                max_height: AtomicUsize::new(1),
490	            }),
491	        }
492	    }
493	
494	    /// Returns `true` if the skip list is empty.
495	    pub fn is_empty(&self) -> bool {
496	        self.len() == 0
497	    }
498	
499	    /// Returns the number of entries in the skip list.
500	    ///
501	    /// If the skip list is being concurrently modified, consider the returned number just an
502	    /// approximation without any guarantees.
503	    pub fn len(&self) -> usize {
504	        let len = self.hot_data.len.load(Ordering::Relaxed);
505	
506	        // Due to the relaxed memory ordering, the length counter may sometimes
507	        // underflow and produce a very large value. We treat such values as 0.
508	        if len > isize::MAX as usize { 0 } else { len }
509	    }
510	
511	    /// Ensures that all `Guard`s used with the skip list come from the same
512	    /// `Collector`.
513	    fn check_guard(&self, guard: &Guard) {
514	        if let Some(c) = guard.collector() {
515	            assert!(c == &self.collector);
516	        }
517	    }
518	}
