520	impl<K, V> SkipList<K, V>
521	where
522	    K: Ord,
523	{
524	    /// Returns the entry with the smallest key.
525	    pub fn front<'a: 'g, 'g>(&'a self, guard: &'g Guard) -> Option<Entry<'a, 'g, K, V>> {
526	        self.check_guard(guard);
527	        let n = self.next_node(self.head.as_tower(), Bound::Unbounded, guard)?;
528	        Some(Entry {
529	            parent: self,
530	            node: n,
531	            guard,
532	        })
533	    }
534	
535	    /// Returns the entry with the largest key.
536	    pub fn back<'a: 'g, 'g>(&'a self, guard: &'g Guard) -> Option<Entry<'a, 'g, K, V>> {
537	        self.check_guard(guard);
538	        let n = self.search_bound::<K>(Bound::Unbounded, true, guard)?;
