998	    /// Inserts an entry with the specified `key` and `value`.
999	    ///
1000	    /// If `replace` is `true`, then any existing entry with this key will first be removed.
1001	    fn insert_internal<F, CompareF>(
1002	        &self,
1003	        key: K,
1004	        value: F,
1005	        replace: CompareF,
1006	        guard: &Guard,
1007	    ) -> RefEntry<'_, K, V>
1008	    where
1009	        F: FnOnce() -> V,
1010	        CompareF: Fn(&V) -> bool,
1011	    {
1012	        self.check_guard(guard);
1013	
1014	        unsafe {
1015	            // Rebind the guard to the lifetime of self. This is a bit of a
1016	            // hack but it allows us to return references that are not bound to
1017	            // the lifetime of the guard.
1018	            let guard = &*(guard as *const _);
1019	
1020	            // First try searching for the key.
1021	            // Note that the `Ord` implementation for `K` may panic during the search.
1022	            let mut search = self.search_position(&key, guard);
1023	            if let Some(r) = search.found {
1024	                let replace = replace(&r.value);
1025	                if !replace {
1026	                    // If a node with the key was found and we're not going to replace it, let's
1027	                    // try returning it as an entry.
1028	                    if let Some(e) = RefEntry::try_acquire(self, r) {
1029	                        return e;
1030	                    }
1031	                }
1032	            }
1033	
1034	            // create value before creating node, so extra allocation doesn't happen if value() function panics
1035	            let value = value();
1036	            // Create a new node.
1037	            let height = self.random_height();
1038	            let (node, n) = {
1039	                // The reference count is initially two to account for:
1040	                // 1. The entry that will be returned.
1041	                // 2. The link at the level 0 of the tower.
1042	                let n = Node::<K, V>::alloc(height, 2);
1043	
1044	                // Write the key and the value into the node.
1045	                ptr::addr_of_mut!((*n).key).write(key);
1046	                ptr::addr_of_mut!((*n).value).write(value);
1047	
1048	                (
1049	                    Shared::<Node<K, V>>::from(n as *const _),
1050	                    NodeRef::new(NonNull::new_unchecked(n)),
1051	                )
1052	            };
1053	
1054	            // Optimistically increment `len`.
1055	            self.hot_data.len.fetch_add(1, Ordering::Relaxed);
1056	
1057	            loop {
1058	                // Set the lowest successor of `n` to `search.right[0]`.
1059	                n.get_level(0).store(search.right[0], Ordering::Relaxed);
1060	
1061	                // Try installing the new node into the skip list (at level 0).
1062	                // TODO(Amanieu): can we use release ordering here?
1063	                if search.left[0]
1064	                    .get_level(0)
1065	                    .compare_exchange(
1066	                        search.right[0],
1067	                        node,
1068	                        Ordering::SeqCst,
1069	                        Ordering::SeqCst,
1070	                        guard,
1071	                    )
1072	                    .is_ok()
1073	                {
1074	                    // This node has been abandoned
1075	                    if let Some(r) = search.found {
1076	                        if r.mark_tower() {
1077	                            self.hot_data.len.fetch_sub(1, Ordering::Relaxed);
1078	                        }
1079	                    }
1080	                    break;
1081	                }
1082	
1083	                // We failed. Let's search for the key and try again.
1084	                {
1085	                    // Create a guard that destroys the new node in case search panics.
1086	                    struct ScopeGuard<K, V>(*const Node<K, V>);
1087	                    impl<K, V> Drop for ScopeGuard<K, V> {
1088	                        fn drop(&mut self) {
1089	                            unsafe { Node::finalize(self.0 as *mut Node<K, V>) }
1090	                        }
1091	                    }
1092	                    let sg = ScopeGuard(node.as_raw());
1093	                    search = self.search_position(&n.key, guard);
1094	                    mem::forget(sg);
1095	                }
1096	
1097	                if let Some(r) = search.found {
1098	                    let replace = replace(&r.value);
1099	                    if !replace {
1100	                        // If a node with the key was found and we're not going to replace it,
1101	                        // let's try returning it as an entry.
1102	                        if let Some(e) = RefEntry::try_acquire(self, r) {
1103	                            // Destroy the new node.
1104	                            Node::finalize(node.as_raw() as *mut Node<K, V>);
1105	                            self.hot_data.len.fetch_sub(1, Ordering::Relaxed);
1106	
1107	                            return e;
1108	                        }
1109	
1110	                        // If we couldn't increment the reference count, that means someone has
1111	                        // just now removed the node.
1112	                    }
1113	                }
1114	            }
1115	
1116	            // The new node was successfully installed. Let's create an entry associated with it.
1117	            let entry = RefEntry {
1118	                parent: self,
1119	                node: n,
1120	            };
1121	
1122	            // Build the rest of the tower above level 0.
1123	            'build: for level in 1..height {
1124	                loop {
1125	                    // Obtain the predecessor and successor at the current level.
1126	                    let pred = search.left[level];
1127	                    let succ = search.right[level];
1128	
1129	                    // Load the current value of the pointer in the tower at this level.
1130	                    // TODO(Amanieu): can we use relaxed ordering here?
1131	                    let next = n.get_level(level).load(Ordering::SeqCst, guard);
1132	
1133	                    // If the current pointer is marked, that means another thread is already
1134	                    // removing the node we've just inserted. In that case, let's just stop
1135	                    // building the tower.
1136	                    if next.tag() == 1 {
1137	                        break 'build;
1138	                    }
1139	
1140	                    // When searching for `key` and traversing the skip list from the highest level
1141	                    // to the lowest, it is possible to observe a node with an equal key at higher
1142	                    // levels and then find it missing at the lower levels if it gets removed
1143	                    // during traversal. Even worse, it is possible to observe completely different
1144	                    // nodes with the exact same key at different levels.
1145	                    //
1146	                    // Linking the new node to a dead successor with an equal key could create
1147	                    // subtle corner cases that would require special care. It's much easier to
1148	                    // simply prohibit linking two nodes with equal keys.
1149	                    //
1150	                    // If the successor has the same key as the new node, that means it is marked
1151	                    // as removed and should be unlinked from the skip list. In that case, let's
1152	                    // repeat the search to make sure it gets unlinked and try again.
1153	                    //
1154	                    // If this comparison or the following search panics, we simply stop building
1155	                    // the tower without breaking any invariants. Note that building higher levels
1156	                    // is completely optional. Only the lowest level really matters, and all the
1157	                    // higher levels are there just to make searching faster.
1158	                    if succ.as_ref().map(|s| &s.key) == Some(&n.key) {
1159	                        search = self.search_position(&n.key, guard);
1160	                        continue;
1161	                    }
1162	
1163	                    // Change the pointer at the current level from `next` to `succ`. If this CAS
1164	                    // operation fails, that means another thread has marked the pointer and we
1165	                    // should stop building the tower.
1166	                    // TODO(Amanieu): can we use release ordering here?
1167	                    if n.get_level(level)
1168	                        .compare_exchange(next, succ, Ordering::SeqCst, Ordering::SeqCst, guard)
1169	                        .is_err()
1170	                    {
1171	                        break 'build;
1172	                    }
1173	
1174	                    // Increment the reference count. The current value will always be at least 1
1175	                    // because we are holding `entry`.
1176	                    n.refs_and_height
1177	                        .fetch_add(1 << HEIGHT_BITS, Ordering::Relaxed);
