1187	                        break;
1188	                    }
1189	
1190	                    // Installation failed. Decrement the reference count.
1191	                    n.refs_and_height
1192	                        .fetch_sub(1 << HEIGHT_BITS, Ordering::Relaxed);
1193	
1194	                    // We don't have the most up-to-date search results. Repeat the search.
1195	                    //
1196	                    // If this search panics, we simply stop building the tower without breaking
1197	                    // any invariants. Note that building higher levels is completely optional.
1198	                    // Only the lowest level really matters, and all the higher levels are there
1199	                    // just to make searching faster.
1200	                    search = self.search_position(&n.key, guard);
